**JavaScript (in pendulum.js)**
```javascript
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');
const initialAngleInput = document.getElementById('initial-angle');
const releaseButton = document.getElementById('release-pendulum');

let initialAngle = 45; // Degrees
let angle = initialAngle;
let velocity = 0;

function drawPendulum() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 20, 0, angle * Math.PI / 180);
  ctx.stroke();
}

function updatePendulum() {
  if (!releaseButton.disabled) {
    angle += velocity;
    velocity -= 0.01 * Math.sin(angle * Math.PI / 180);
    if (angle > 180 || angle < 0) {
      angle = 180 - angle;
      velocity = -velocity;
    }
  }
  requestAnimationFrame(updatePendulum);
}

releaseButton.addEventListener('click', () => {
  releaseButton.disabled = true;
  velocity = initialAngle / 180 * Math.PI;
  updatePendulum();
});

initialAngleInput.addEventListener('input', () => {
  initialAngle = parseInt(initialAngleInput.value);
});

drawPendulum();
```
**How it works**

1. The user inputs the initial angle of the pendulum in the input field.
2. When the "Release Pendulum" button is clicked, the pendulum starts swinging. The angle and velocity of the pendulum are updated every frame using the equations of motion for simple harmonic motion.
3. The `drawPendulum` function is called every frame to draw the pendulum on the canvas.
4. The pendulum continues to swing until it reaches a point where its velocity is almost zero, at which point it is considered to have stopped.

